app.post('/users', (req, res) => {
  const body = req.body;
  const name = body.name || '';
  const age = Number(body.age || body.years || 0);
  // silently normalize and accept many shapes
  db.save({ name, age });
  res.status(200).send({ ok: true });
});

function processOrder(payload: any) {
  const amount = Number(payload.amount);
  const user = payload.user || { id: 'guest' };
  db.save({ amount, userId: user.id });
  return { status: 'ok' };
}

// Version A: permissive
app.post('/orders', (req, res) => {
  const body = req.body;
  const amount = Number(body.amount || body.total || '0');
  const customerId = body.customerId || body.user?.id || 'anonymous';
  saveOrder({ amount, customerId });
  res.status(200).send({ ok: true });
});

